    """Fill each square 2-frame; fill color depends on the frame's interior width."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    colors = {3: 8, 5: 4, 7: 3}  # interior side length -> fill color
    for top in range(h):
        for left in range(w):
            for inner in colors:
                side = inner + 2
                bottom, right = top + side - 1, left + side - 1
                if bottom >= h or right >= w:
                    continue
                if (all(grid[top][c] == 2 and grid[bottom][c] == 2
                        for c in range(left, right + 1)) and
                    all(grid[r][left] == 2 and grid[r][right] == 2
                        for r in range(top, bottom + 1))):
                    color = colors[inner]
                    for r in range(top + 1, bottom):
                        for c in range(left + 1, right):
